const {
  getFunctionParameters,
  iterateFunctionParametersPath,
  hasComment,
  CommentCheckFlags,
  isFunctionCompositionArgs,
  isJSXNode,
  isLongCurriedCallExpression,
  shouldPrintComma,
  getCallArguments,
  iterateCallArgumentsPath,
} = require("../utils");
const { locEnd } = require("../loc");

const {
  builders: {
    concat,
    line,
    hardline,
    softline,
    group,
    indent,
    conditionalGroup,
    ifBreak,
    breakParent,
  },
  utils: { willBreak },
} = require("../../document");

