      ifBreak(shouldPrintComma(options, "all") && !hasRest ? "," : ""),
      printDanglingComments(path, options, /* sameIndent */ true),
      softline,
      "]",
    ])
  );
}

module.exports = {
  printOpaqueType,
  printTypeAlias,
  printIntersectionType,
  printUnionType,
  printFunctionType,
  printTupleType,
  shouldHugType,
};

